import hashlib
import uuid
from datetime import datetime, timezone


class User:
    _store = {}

    def __init__(self, name, email, password, role="user"):
        self.id = str(uuid.uuid4())
        self.name = name
        self.email = email
        self._password_hash = self._hash_password(password)
        self.role = role
        self.created_at = datetime.now(timezone.utc)
        self.updated_at = datetime.now(timezone.utc)

    @staticmethod
    def _hash_password(password):
        return hashlib.sha256(password.encode()).hexdigest()

    def check_password(self, password):
        return self._password_hash == self._hash_password(password)

    def to_dict(self):
        return {
            "id": self.id,
            "name": self.name,
            "email": self.email,
            "role": self.role,
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
        }

    @classmethod
    def create(cls, name, email, password, role="user"):
        if email in cls._store:
            raise ValueError("User with this email already exists")
        user = cls(name, email, password, role)
        cls._store[email] = user
        return user

    @classmethod
    def find_by_email(cls, email):
        return cls._store.get(email)

    @classmethod
    def find_by_id(cls, user_id):
        for user in cls._store.values():
            if user.id == user_id:
                return user
        return None

    @classmethod
    def list_all(cls):
        return list(cls._store.values())

    @classmethod
    def delete(cls, email):
        return cls._store.pop(email, None)

    @classmethod
    def count(cls):
        return len(cls._store)

    @classmethod
    def reset(cls):
        cls._store.clear()

import jwt
from datetime import datetime, timezone, timedelta
from functools import wraps
from flask import request, g

from config import SECRET_KEY, JWT_ALGORITHM, JWT_EXPIRATION_SECONDS
from models.user import User


def create_token(email):
    payload = {
        "sub": email,
        "iat": datetime.now(timezone.utc),
        "exp": datetime.now(timezone.utc) + timedelta(seconds=JWT_EXPIRATION_SECONDS),
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM)


def decode_token(token):
    return jwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])


def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return {"error": "Missing or invalid Authorization header"}, 401

        token = auth_header.split(" ", 1)[1]
        try:
            payload = decode_token(token)
        except jwt.ExpiredSignatureError:
            return {"error": "Token has expired"}, 401
        except jwt.InvalidTokenError:
            return {"error": "Invalid token"}, 401

        user = User.find_by_email(payload["sub"])
        if not user:
            return {"error": "User not found"}, 401

        g.current_user = user
        return f(*args, **kwargs)

    return decorated


def admin_required(f):
    @wraps(f)
    @login_required
    def decorated(*args, **kwargs):
        if g.current_user.role != "admin":
            return {"error": "Admin access required"}, 403
        return f(*args, **kwargs)

    return decorated

from flask import jsonify
from marshmallow import ValidationError


def register_error_handlers(app):
    @app.errorhandler(400)
    def bad_request(e):
        return jsonify({"error": "Bad request", "message": str(e)}), 400

    @app.errorhandler(404)
    def not_found(e):
        return jsonify({"error": "Not found", "message": str(e)}), 404

    @app.errorhandler(405)
    def method_not_allowed(e):
        return jsonify({"error": "Method not allowed", "message": str(e)}), 405

    @app.errorhandler(429)
    def rate_limited(e):
        return jsonify({"error": "Too many requests", "message": str(e)}), 429

    @app.errorhandler(500)
    def internal_error(e):
        return jsonify({"error": "Internal server error", "message": "An unexpected error occurred"}), 500

    @app.errorhandler(ValidationError)
    def validation_error(e):
        return jsonify({"error": "Validation failed", "messages": e.messages}), 422

    @app.errorhandler(ValueError)
    def value_error(e):
        return jsonify({"error": "Invalid request", "message": str(e)}), 400

from marshmallow import Schema, fields, validate, ValidationError


def not_blank(value):
    if not value.strip():
        raise ValidationError("Field cannot be blank")


class RegisterSchema(Schema):
    name = fields.String(required=True, validate=[not_blank, validate.Length(min=1, max=100)])
    email = fields.Email(required=True)
    password = fields.String(required=True, validate=validate.Length(min=6, max=128))
    role = fields.String(validate=validate.OneOf(["user", "admin"]), missing="user")


class LoginSchema(Schema):
    email = fields.Email(required=True)
    password = fields.String(required=True)


class UserUpdateSchema(Schema):
    name = fields.String(validate=[not_blank, validate.Length(min=1, max=100)])
    role = fields.String(validate=validate.OneOf(["user", "admin"]))


class PaginationSchema(Schema):
    page = fields.Integer(validate=validate.Range(min=1), missing=1)
    per_page = fields.Integer(validate=validate.Range(min=1, max=100), missing=20)

from flask import request

from config import ITEMS_PER_PAGE, MAX_PER_PAGE


def paginate(items, schema=None):
    try:
        page = int(request.args.get("page", 1))
    except (ValueError, TypeError):
        page = 1
    try:
        per_page = int(request.args.get("per_page", ITEMS_PER_PAGE))
    except (ValueError, TypeError):
        per_page = ITEMS_PER_PAGE

    if page < 1:
        page = 1
    if per_page < 1:
        per_page = 1
    if per_page > MAX_PER_PAGE:
        per_page = MAX_PER_PAGE

    total = len(items)
    total_pages = max(1, (total + per_page - 1) // per_page)
    page = min(page, total_pages)

    start = (page - 1) * per_page
    end = start + per_page
    page_items = items[start:end]

    data = [item.to_dict() for item in page_items] if not schema else schema.dump(page_items, many=True)

    return {
        "data": data,
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
            "has_next": page < total_pages,
            "has_prev": page > 1,
        },
    }

